//! Static asset and SPA route serving for the embedded `web/dist` frontend.

use crate::error::not_found;
use axum::{
    http::{Method, StatusCode, Uri, header},
    response::{IntoResponse, Response},
};

/// Embedded frontend files generated by `build.rs` from `web/dist` (empty if built without
/// `web/dist`).
static FILES: &[(&str, &[u8])] = include!(concat!(env!("OUT_DIR"), "/web_files.rs"));

/// Serves a static file from `web/dist`, falling back to `index.html` for extensionless SPA routes
/// outside `/api/`.
pub async fn serve_page(method: Method, uri: Uri) -> Response {
    let path = uri.path().trim_start_matches('/');
    let last = path.rsplit('/').next().unwrap_or_default();
    let is_route = !path.starts_with("api/") && !last.contains('.');
    let file = find_file(path).or_else(|| is_route.then(|| find_file("index.html")).flatten());
    let Some((name, body)) = file.filter(|_| matches!(method, Method::GET | Method::HEAD)) else {
        return not_found().into_response();
    };
    let content_type = match name.rsplit('.').next() {
        Some("html") => "text/html; charset=utf-8",
        Some("js") => "text/javascript",
        Some("css") => "text/css",
        Some("svg") => "image/svg+xml",
        Some("json") => "application/json",
        Some("png") => "image/png",
        Some("woff2") => "font/woff2",
        _ => "application/octet-stream",
    };
    // Assets under `assets/` include content hashes in their filenames and can be cached immutable.
    let cache = if name.starts_with("assets/") {
        "public, max-age=31536000, immutable"
    } else {
        "no-cache"
    };
    let headers = [
        (header::CONTENT_TYPE, content_type),
        (header::CACHE_CONTROL, cache),
        (header::CONTENT_SECURITY_POLICY, PAGE_CSP),
    ];
    (headers, *body).into_response()
}

/// Renders `index.html` with `problem` embedded in a `<meta name="ito-problem">` tag so the SPA
/// displays its error view with HTTP status `status`. Returns `None` if `web/dist` is not embedded.
pub fn render_problem_page(status: StatusCode, problem: &[u8]) -> Option<Response> {
    let (_, index) = find_file("index.html")?;
    let page = embed_problem(index, problem)?;
    let headers = [
        (header::CONTENT_TYPE, "text/html; charset=utf-8"),
        (header::CACHE_CONTROL, "no-store"),
        (header::CONTENT_SECURITY_POLICY, PAGE_CSP),
    ];
    Some((status, headers, page).into_response())
}

const PAGE_CSP: &str = "default-src 'self'; style-src 'self' 'unsafe-inline'; img-src 'self' data:; \
     object-src 'none'; base-uri 'none'; frame-ancestors 'none'";

fn find_file(name: &str) -> Option<&'static (&'static str, &'static [u8])> {
    FILES.iter().find(|(n, _)| *n == name)
}

/// Injects `<meta name="ito-problem" content="…">` right before `</head>` in `index`, HTML-escaping
/// the attribute value.
fn embed_problem(index: &[u8], problem: &[u8]) -> Option<Vec<u8>> {
    let end = index.windows(7).position(|w| w == b"</head>")?;
    let mut meta = b"<meta name=\"ito-problem\" content=\"".to_vec();
    for &b in problem {
        match b {
            b'&' => meta.extend_from_slice(b"&amp;"),
            b'"' => meta.extend_from_slice(b"&quot;"),
            b'<' => meta.extend_from_slice(b"&lt;"),
            b'>' => meta.extend_from_slice(b"&gt;"),
            b => meta.push(b),
        }
    }
    meta.extend_from_slice(b"\">");
    Some([&index[..end], &meta, &index[end..]].concat())
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn problems_sit_escaped_in_the_head() {
        let index = b"<html><head><title>Ito</title></head><body></body></html>";
        let problem = br#"{"title":"<b>\"&"}"#;
        let page = embed_problem(index, problem).unwrap();
        let meta = r#"<meta name="ito-problem" content="{&quot;title&quot;:&quot;&lt;b&gt;\&quot;&amp;&quot;}">"#;
        let expected = format!("<html><head><title>Ito</title>{meta}</head><body></body></html>");
        assert_eq!(String::from_utf8(page).unwrap(), expected);
    }

    #[test]
    fn pages_without_a_head_take_no_problem() {
        assert_eq!(embed_problem(b"<p>no head</p>", b"{}"), None);
    }
}
